SourceCode.Declaration:
/// <summary>
/// One key range of one area of an item snapshot build: a task HSMobileOpsSkuSnapshotBuild adds to
/// its batch job, so the ranges are written side by side. Its end is counted on the snapshot row;
/// the last task to end completes the build.
/// </summary>
class HSMobileOpsSkuSnapshotTask extends RunBaseBatch
{
    RefRecId snapshot;
    str      area;
    int      taskIndex;
    str      after;
    str      upTo;
    str      scope;

    #define.CurrentVersion(2)
    #localmacro.CurrentList
        snapshot,
        area,
        taskIndex,
        after,
        upTo,
        scope
    #endmacro
}

Method.Source:
public static HSMobileOpsSkuSnapshotTask newTask(RefRecId _snapshot, str _area, int _index, str _after, str _upTo, str _scope = '')
{
    HSMobileOpsSkuSnapshotTask task = new HSMobileOpsSkuSnapshotTask();

    task.parmSnapshot(_snapshot);
    task.parmArea(_area);
    task.parmIndex(_index);
    task.parmAfter(_after);
    task.parmUpTo(_upTo);
    task.parmScope(_scope);
    task.batchInfo().parmCaption(_area == 'STORE'
        ? strFmt('Mobile ops: item snapshot of store %1 (%2 with this assortment)', _scope, _index)
        : (_scope
            ? strFmt('Mobile ops: item snapshot of store %1 %2', _scope, _area)
            : strFmt('Mobile ops: item snapshot %1 %2', _area, _index)));
    return task;
}

public RefRecId parmSnapshot(RefRecId _snapshot = snapshot)
{
    snapshot = _snapshot;
    return snapshot;
}

public str parmArea(str _area = area)
{
    area = _area;
    return area;
}

public int parmIndex(int _index = taskIndex)
{
    taskIndex = _index;
    return taskIndex;
}

public str parmAfter(str _after = after)
{
    after = _after;
    return after;
}

public str parmUpTo(str _upTo = upTo)
{
    upTo = _upTo;
    return upTo;
}

/// <summary>'' for every item; a warehouse for its store's assortment.</summary>
public str parmScope(str _scope = scope)
{
    scope = _scope;
    return scope;
}

/// <summary>
/// The range's parts are numbered taskIndex * 10000 + 1, 2, ... so the ranges keep their order;
/// the build numbers them 1..n at the end. An error is recorded, not thrown: the build fails
/// once every task has ended.
/// </summary>
public void run()
{
    str failure;

    // A store's snapshot cut from the company's: after = the company snapshot, upTo = the
    // snapshot rows of the other stores with the same assortment.
    if (area == 'STORE')
    {
        HSMobileOpsSkuSnapshotBuild::buildStoreGroup(snapshot, str2Int64(after), upTo ? str2Con(upTo, ',') : conNull(), scope);
        return;
    }

    try
    {
        HSMobileOpsSkuSnapshotBuild::writeArea(snapshot, area, after, upTo, taskIndex * 10000, scope);
    }
    catch (Exception::CLRError)
    {
        failure = HSMobileOpsSkuSnapshotBuild::clrFailure();
    }
    catch
    {
        failure = HSMobileOpsSkuSnapshotBuild::lastInfo();
        if (!failure)
        {
            failure = 'error';
        }
    }
    HSMobileOpsSkuSnapshotBuild::taskEnded(snapshot, failure ? strFmt('%1 %2: %3', area, taskIndex, failure) : '', this.parmCurrentBatch());
}

public boolean unpack(container _packedClass)
{
    Version version = RunBase::getVersion(_packedClass);

    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList] = _packedClass;
            break;
        default:
            return false;
    }
    return true;
}

/// <summary>
/// A rerun would write its parts again next to the first ones.
/// </summary>

public boolean isRetryable()
{
    return false;
}

public static ClassDescription description()
{
    return 'Mobile ops: item snapshot task';
}
